package org.eclipse.kura.core.token.jwt.issuer;

import java.util.List;

import org.eclipse.kura.core.testutil.pki.TestCA.TestCAException;
import org.eclipse.kura.core.token.jwt.common.AbstractJwtScenario;
import org.eclipse.kura.core.token.jwt.common.IssuingConfig;
import org.eclipse.kura.security.token.TokenIssueRequest;
import org.junit.Test;

public class AudienceClaimTest extends AbstractJwtScenario {

    @Test
    public void withoutAnIntendedConsumerNoAudienceClaimIsIssued() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsIssuedFor(TEST_IDENTITY);

        thenATokenIsIssued();
        thenIssuedTokenHasNoClaim("aud");
    }

    @Test
    public void oneIntendedConsumerIsIssuedAsASingleAudience() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedFor("kura.rest");

        thenIssuedTokenHasStringClaim("aud", "kura.rest");
    }

    @Test
    public void severalIntendedConsumersAreIssuedAsAnAudienceArray() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedFor("kura.rest", "kura.web");

        thenIssuedTokenHasStringArrayClaim("aud", List.of("kura.rest", "kura.web"));
    }

    @Test
    public void repeatedIntendedConsumersAreIssuedOnlyOnce() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedFor("kura.rest", "kura.rest");

        thenIssuedTokenHasStringClaim("aud", "kura.rest");
    }

    private void givenAnIssuerWithASigningKey() throws TestCAException {
        givenKeystorePrivateKeyEntry(SIGNING_ALIAS, 0);
        givenTheIssuerIsBoundToTheKeystore();
        givenTheIssuerIsActivatedWith(IssuingConfig.defaults().withSigningKeyAlias(SIGNING_ALIAS));
    }

    private void whenATokenIsRequestedFor(final String... intendedConsumers) {
        final TokenIssueRequest.Builder builder = TokenIssueRequest.builder(TEST_IDENTITY);

        for (final String intendedConsumer : intendedConsumers) {
            builder.intendedConsumer(intendedConsumer);
        }

        whenATokenIsIssued(builder.build());
    }

}
